static int32_t ui_demo_clamp_percent(int32_t percent)
{
  if (percent < 0)
    {
      return 0;
    }

  if (percent > 100)
    {
      return 100;
    }

  return percent;
}

static void ui_demo_copy_text(char *dst, size_t dst_len, const char *src)
{
  if (dst_len == 0)
